package io.lumine.mythic.lib.api.crafting.ingredients;
import io.lumine.mythic.lib.api.crafting.uimanager.ProvidedUIFilter; import io.lumine.mythic.lib.api.util.ui.FriendlyFeedbackProvider; import net.minecraft.item.ItemStack; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public class MythicIngredient implements Cloneable { private static final Map<String,MythicIngredient> ENABLED=new ConcurrentHashMap<>(); private final String name; private final ArrayList<ProvidedUIFilter> substitutes; public MythicIngredient(String n,ArrayList<ProvidedUIFilter> s){name=n;substitutes=new ArrayList<>(s);} public MythicIngredient(String n,ProvidedUIFilter... s){this(n,new ArrayList<>(Arrays.asList(s)));} public String getName(){return name;} public void addSubstitute(ProvidedUIFilter f){substitutes.add(f);} public ArrayList<ProvidedUIFilter> getSubstitutes(){return new ArrayList<>(substitutes);} public void clearSubstitutes(){substitutes.clear();} public boolean acceptsAir(){return substitutes.stream().anyMatch(ProvidedUIFilter::isAir);} public boolean matches(ItemStack stack,FriendlyFeedbackProvider fb){return substitutes.stream().anyMatch(f->f.matches(stack,true,fb));} public static void enable(MythicIngredient i){ENABLED.put(i.name.toLowerCase(Locale.ROOT),i);} public static MythicIngredient get(String n){return ENABLED.get(n.toLowerCase(Locale.ROOT));} public static ArrayList<String> getEnabledIngredients(){return new ArrayList<>(ENABLED.keySet());} public MythicIngredient clone(){return new MythicIngredient(name,substitutes.stream().map(ProvidedUIFilter::clone).toArray(ProvidedUIFilter[]::new));} public boolean isDefinesItem(){return substitutes.size()==1&&substitutes.get(0).getParent().fullyDefinesItem();} public ItemStack getRandomSubstituteItem(FriendlyFeedbackProvider fb){return substitutes.isEmpty()?ItemStack.EMPTY:substitutes.get(0).getItemStack(fb);} public ItemStack getRandomDisplayItem(FriendlyFeedbackProvider fb){return substitutes.isEmpty()?ItemStack.EMPTY:substitutes.get(0).getDisplayStack(fb);} public ProvidedUIFilter getRandomSubstitute(boolean ignored){return substitutes.isEmpty()?null:substitutes.get(0);} }
